module dma_controller (
    input clk,
    input rst,
    input [3:0] req,
    output reg [3:0] ack
);
    reg [1:0] current_channel;
    reg [1:0] next_channel;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            current_channel <= 2'b00;
            ack <= 4'b0000;
        end else begin
            if (req[current_channel]) begin
                ack <= 4'b0000;
                ack[current_channel] <= 1'b1; // Acknowledge the current channel
            end else begin
                ack <= 4'b0000; // No acknowledgment if no request
            end
            next_channel <= current_channel + 1;
            if (next_channel > 2'b11)
                next_channel <= 2'b00; // Wrap around
            current_channel <= next_channel;
        end
    end
endmodule

