module uart_transmitter (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire send,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600; // Configurable baud rate
    localparam CLK_FREQ = 50000000; // Example clock frequency
    localparam BIT_PERIOD = CLK_FREQ / BAUD_RATE;

    reg [3:0] bit_count;
    reg [15:0] clk_count;
    reg [7:0] buffer;
    reg transmitting;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx <= 1;
            busy <= 0;
            transmitting <= 0;
            clk_count <= 0;
            bit_count <= 0;
        end else if (send && !busy) begin
            busy <= 1;
            transmitting <= 1;
            buffer <= data_in;
            clk_count <= 0;
            bit_count <= 0;
            tx <= 0; // Start bit
        end else if (busy) begin
            if (clk_count < BIT_PERIOD - 1) begin
                clk_count <= clk_count + 1;
            end else begin
                clk_count <= 0;
                if (transmitting) begin
                    if (bit_count < 8) begin
                        tx <= buffer[bit_count]; // Send data bits
                        bit_count <= bit_count + 1;
                    end else begin
                        tx <= 1; // Stop bit
                        busy <= 0; // Transmission complete
                        transmitting <= 0;
                    end
                end
            end
        end
    end
endmodule

