module adc_controller(
    input clk,
    input reset,
    input start,
    output reg [23:0] digital_out,
    output reg done
);
    reg [3:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            digital_out <= 0;
            done <= 0;
        end else if (start) begin
            if (count < 10) begin
                count <= count + 1;
                digital_out <= digital_out + 1; // Simulate ADC conversion
                done <= 0;
            end else begin
                done <= 1;
            end
        end
    end
endmodule

