module sd_card_controller (
    input clk,
    input rst,
    input start,
    input [7:0] write_data,
    output reg [7:0] read_data,
    output reg busy,
    output reg ready,
    output reg [1:0] state // 2-bit state for simplicity
);
    // State encoding
    localparam IDLE = 2'b00,
               INIT = 2'b01,
               READ = 2'b10,
               WRITE = 2'b11;

    reg [1:0] next_state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            busy <= 0;
            ready <= 1;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            IDLE: begin
                busy = 0;
                ready = 1;
                if (start) begin
                    next_state = INIT;
                end else begin
                    next_state = IDLE;
                end
            end

            INIT: begin
                busy = 1;
                ready = 0;
                // Assume initialization takes one clock cycle
                next_state = READ; // Go to READ after INIT for demonstration
            end

            READ: begin
                busy = 1;
                ready = 0;
                // Simulate reading data
                read_data = 8'hFF; // Dummy read data
                next_state = IDLE; // Go back to IDLE after read
            end

            WRITE: begin
                busy = 1;
                ready = 0;
                // Simulate write operation (not really writing in this dummy implementation)
                next_state = IDLE; // Go back to IDLE after write
            end

            default: begin
                next_state = IDLE;
            end
        endcase
    end
endmodule

