module kalman_filter (
    input clk,
    input reset,
    input [15:0] z,    // Measured Position
    input [15:0] v,    // Measured Velocity
    output reg [15:0] x_est,  // Estimated Position
    output reg [15:0] v_est   // Estimated Velocity
);
    reg [15:0] k_pos;  // Kalman Gain for Position
    reg [15:0] k_vel;  // Kalman Gain for Velocity

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            x_est <= 16'd0;
            v_est <= 16'd0;
            k_pos <= 16'd1; // Initial Kalman Gain for position
            k_vel <= 16'd1; // Initial Kalman Gain for velocity
        end else begin
            // Kalman Filter update equations
            x_est <= x_est + k_pos * (z - x_est);
            v_est <= v_est + k_vel * (v - v_est);
        end
    end
endmodule

