module PLL (  
    input wire clk_in,  
    input wire reset,  
    input wire [1:0] freq_select,  
    output reg clk_out  
);  

    reg [3:0] counter;  
    reg vco_clk;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            vco_clk <= 0;  
        end else begin  
            counter <= counter + 1;  
            if (counter == freq_select) begin  
                vco_clk <= ~vco_clk;  
            end  
        end  
    end  

    always @(posedge vco_clk or posedge reset) begin  
        if (reset)  
            clk_out <= 0;  
        else  
            clk_out <= ~clk_out;  
    end  
endmodule

