module pitch_detector(
    input clk,
    input signal_in,
    output reg freq_above_threshold
);
    parameter THRESHOLD = 5; // Example threshold value
    reg [3:0] count;

    always @(posedge clk) begin
        if (signal_in) begin
            count <= count + 1;
        end else begin
            if (count >= THRESHOLD) begin
                freq_above_threshold <= 1;
            end else begin
                freq_above_threshold <= 0;
            end
            count <= 0; // Reset count after processing
        end
    end
endmodule

