module pulse_generator(
    input clk,
    input reset,
    input [3:0] pulse_width,
    input [3:0] period,
    output reg pulse_out
);
    reg [3:0] count;
    reg [3:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pulse_out <= 0;
            count <= 0;
            state <= 0;
        end else begin
            if (state < pulse_width) begin
                pulse_out <= 1;
                count <= count + 1;
                state <= state + 1;
            end else if (state < (pulse_width + period)) begin
                pulse_out <= 0;
                count <= count + 1;
                state <= state + 1;
            end else begin
                state <= 0; // reset state to generate the next pulse
            end
        end
    end
endmodule

