    input reset,
    input [7:0] binary_input, // 8-bit binary input for one OFDM symbol
    input valid,
    output reg [15:0] I_out, // Output I signal
    output reg [15:0] Q_out, // Output Q signal
    output reg valid_out
);
    parameter NUM_SUBCARRIERS = 4;

