    reg [15:0] ifft_output [0:NUM_SUBCARRIERS-1];

    // Simple IFFT for demonstration (should be replaced with actual IFFT implementation)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            valid_out <= 0;
        end else if (valid && count < NUM_SUBCARRIERS) begin
            symbols[count] <= binary_input;
            count <= count + 1;
            if (count == NUM_SUBCARRIERS - 1) begin
                // IFFT operation simulation (simple mapping for demonstration)
