module deserializer (
    input clk,
    input rst,
    input serial_in,
    output reg [15:0] parallel_out
);
    reg [3:0] bit_count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            parallel_out <= 16'b0;
            bit_count <= 4'b0;
        end else begin
            if (bit_count < 16) begin
                parallel_out <= {parallel_out[14:0], serial_in}; // Shift left and add new bit
                bit_count <= bit_count + 1;
            end
        end
    end
endmodule

