module spi_master(  
    input clk,  
    input reset,  
    input start,  
    input [7:0] data_in,  
    output reg sclk,  
    output reg mosi,  
    output reg cs  
);  
    reg [3:0] bit_index;  
    reg [7:0] data;  
    reg state;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            sclk <= 0;  
            mosi <= 0;  
            cs <= 1;  
            bit_index <= 0;  
            state <= 0;  
        end else begin  
            if (start && state == 0) begin  
                data <= data_in;  
                cs <= 0;  
                state <= 1;  
                bit_index <= 0;  
            end else if (state == 1) begin  
                if (bit_index < 8) begin  
                    sclk <= ~sclk;  
                    if (sclk) begin  
                        mosi <= data[7 - bit_index];  
                        bit_index <= bit_index + 1;  
                    end  
                end else begin  
                    cs <= 1;  
                    sclk <= 0;  
                    state <= 0;  
                end  
            end  
        end  
    end  
endmodule

