    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            counter <= 0;
            clk_out <= 0;
            frac_counter <= 0;
        end else begin
            if (counter < (divider + (frac_counter < frac ? 1 : 0))) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                clk_out <= ~clk_out;
                if (frac_counter < frac) begin
                    frac_counter <= frac_counter + 1;
                end else begin
                    frac_counter <= 0;
                end
            end
        end
    end
endmodule

