module IFFT_4point(  
    input clk,  
    input rst_n,  
    input valid_in,  
    input [15:0] x0_real,  
    input [15:0] x0_imag,  
    input [15:0] x1_real,  
    input [15:0] x1_imag,  
    input [15:0] x2_real,  
    input [15:0] x2_imag,  
    input [15:0] x3_real,  
    input [15:0] x3_imag,  
    output reg valid_out,  
    output reg [15:0] y0_real,  
    output reg [15:0] y0_imag,  
    output reg [15:0] y1_real,  
    output reg [15:0] y1_imag,  
    output reg [15:0] y2_real,  
    output reg [15:0] y2_imag,  
    output reg [15:0] y3_real,  
    output reg [15:0] y3_imag  
);  
    reg [3:0] state;  
    reg [15:0] temp_real[0:3];  
    reg [15:0] temp_imag[0:3];  
    parameter IDLE = 4'd0, PROCESS = 4'd1, OUTPUT = 4'd2;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            state <= IDLE;  
            valid_out <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (valid_in) begin  
                        temp_real[0] = x0_real;  
                        temp_imag[0] = x0_imag;  
                        temp_real[1] = x1_real;  
                        temp_imag[1] = x1_imag;  
                        temp_real[2] = x2_real;  
                        temp_imag[2] = x2_imag;  
                        temp_real[3] = x3_real;  
                        temp_imag[3] = x3_imag;  
                        state <= PROCESS;  
                    end  
                end  
                PROCESS: begin  
                    // Basic IFFT computation (not optimized for performance)  
                    y0_real <= (temp_real[0] + temp_real[1] + temp_real[2] + temp_real[3]) >> 2;  
                    y0_imag <= (temp_imag[0] + temp_imag[1] + temp_imag[2] + temp_imag[3]) >> 2;  
                    y1_real <= (temp_real[0] + temp_real[1] - temp_real[2] - temp_real[3]) >> 2;  
                    y1_imag <= (temp_imag[0] + temp_imag[1] - temp_imag[2] - temp_imag[3]) >> 2;  
                    y2_real <= (temp_real[0] - temp_real[1] + temp_real[2] - temp_real[3]) >> 2;  
                    y2_imag <= (temp_imag[0] - temp_imag[1] + temp_imag[2] - temp_imag[3]) >> 2;  
                    y3_real <= (temp_real[0] - temp_real[1] - temp_real[2] + temp_real[3]) >> 2;  
                    y3_imag <= (temp_imag[0] - temp_imag[1] - temp_imag[2] + temp_imag[3]) >> 2;  
                    state <= OUTPUT;  
                end  
                OUTPUT: begin  
                    valid_out <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

