module rrt_node_insertion(
    input clk,
    input [7:0] x,
    input [7:0] y,
    input [7:0] tx,
    input [7:0] ty,
    output reg [7:0] new_x,
    output reg [7:0] new_y,
    output reg node_added
);
    parameter STEP_SIZE = 5;

    always @(posedge clk) begin
        if (new_x < tx) begin
            new_x <= new_x + STEP_SIZE;
        end else if (new_x > tx) begin
            new_x <= new_x - STEP_SIZE;
        end

        if (new_y < ty) begin
            new_y <= new_y + STEP_SIZE;
        end else if (new_y > ty) begin
            new_y <= new_y - STEP_SIZE;
        end

        if ((new_x == tx) && (new_y == ty)) begin
            node_added <= 1;
        end else begin
            node_added <= 0;
        end
    end

    initial begin
        new_x = x;
        new_y = y;
        node_added = 0;
    end
endmodule

