module reset_controller(
    input clk,
    input reset,
    input enable,
    output reg [3:0] output_reg
);
    always @(posedge clk or posedge reset) begin
        if (reset) 
            output_reg <= 4'b0000;
        else if (enable) 
            output_reg <= output_reg + 1;
    end
endmodule

module spi_master (
    input wire clk,
    input wire start,
    input wire [7:0] data_in,
    output reg [7:0] data_out,
    output reg busy,
    output reg done
);
    reg [2:0] bit_count;
    reg [7:0] shift_reg;

    always @(posedge clk) begin
        if (start) begin
            busy <= 1'b1;
            done <= 1'b0;
            shift_reg <= data_in;
            bit_count <= 3'b000;
        end else if (busy) begin
            data_out[bit_count] <= shift_reg[7];
            shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left
            bit_count <= bit_count + 1;

            if (bit_count == 3'b111) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
        end
    end
endmodule

