module counter_2bit (  
    input clk,  
    input reset,  
    output reg [1:0] count  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 2'b00;  
        end else begin  
            count <= count + 1;  
        end  
    end  
endmodule

module uart_receiver(  
    input clk,  
    input rst_n,  
    input rx,  
    output reg [7:0] data_out,  
    output reg data_ready  
);  
    reg [3:0] state;  
    reg [3:0] bit_index;  
    reg [7:0] shift_reg;  
    parameter IDLE = 4'b0000, START = 4'b0001, DATA = 4'b0010, STOP = 4'b0011;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            state <= IDLE;  
            bit_index <= 0;  
            data_out <= 0;  
            data_ready <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    data_ready <= 0;  
                    if (rx == 0) begin // Start bit detected  
                        state <= START;  
                    end  
                end  
                START: begin  
                    state <= DATA;  
                    bit_index <= 0;  
                end  
                DATA: begin  
                    shift_reg[bit_index] <= rx;  
                    if (bit_index == 7) begin // All bits received  
                        state <= STOP;  
                    end else begin  
                        bit_index <= bit_index + 1;  
                    end  
                end  
                STOP: begin  
                    data_out <= shift_reg;  
                    data_ready <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

module uart_transmitter(  
    input wire clk,  
    input wire reset,  
    input wire [7:0] data_in,  
    input wire send,  
    output reg tx,  
    output reg busy  
);  
    parameter BAUD_RATE = 9600;  
    parameter CLOCK_FREQ = 50000000;  
    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;  
    localparam STOP_BIT = 1;  
    localparam START_BIT = 0;  
    reg [3:0] bit_index;  
    reg [12:0] counter;  
    reg [9:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            busy <= 0;  
            tx <= 1;  
            bit_index <= 0;  
            counter <= 0;  
        end else begin  
            if (send && !busy) begin  
                busy <= 1;  
                shift_reg <= {STOP_BIT, data_in, START_BIT};  
                bit_index <= 0;  
                counter <= 0;  
            end  

            if (busy) begin  
                if (counter < BIT_PERIOD - 1) begin  
                    counter <= counter + 1;  
                end else begin  
                    counter <= 0;  
                    tx <= shift_reg[bit_index];  
                    if (bit_index < 9) begin  
                        bit_index <= bit_index + 1;  
                    end else begin  
                        busy <= 0;  
                    end  
                end  
            end  
        end  
    end  
endmodule

module dram_cell (
    input wire data_in,
    input wire write_enable,
    input wire read_enable,
    output reg data_out
);
    reg stored_bit;

    always @(posedge write_enable) begin
        if (write_enable) begin
            stored_bit <= data_in;
        end
    end

    always @(posedge read_enable) begin
        if (read_enable) begin
            data_out <= stored_bit;
        end
    end

    initial begin
        stored_bit = 0;
        data_out = 0;
    end
endmodule

