        data_out <= data_in;
    end
endmodule

module linear_regression (
    input [15:0] x0, input [15:0] y0,
    input [15:0] x1, input [15:0] y1,
    input [15:0] x2, input [15:0] y2,
    input [15:0] x3, input [15:0] y3,
    input [15:0] x4, input [15:0] y4,
    output reg [15:0] m, // slope
    output reg [15:0] b  // y-intercept
);
    reg signed [31:0] sx, sy, sxy, sx2;
    integer i;

    always @(*) begin
        sx = 0; sy = 0; sxy = 0; sx2 = 0;

        // Calculate sums
        for (i = 0; i < 5; i = i + 1) begin
            case (i)
                0: begin sx = sx + x0; sy = sy + y0; sxy = sxy + (x0 * y0); sx2 = sx2 + (x0 * x0); end
                1: begin sx = sx + x1; sy = sy + y1; sxy = sxy + (x1 * y1); sx2 = sx2 + (x1 * x1); end
                2: begin sx = sx + x2; sy = sy + y2; sxy = sxy + (x2 * y2); sx2 = sx2 + (x2 * x2); end
                3: begin sx = sx + x3; sy = sy + y3; sxy = sxy + (x3 * y3); sx2 = sx2 + (x3 * x3); end
                4: begin sx = sx + x4; sy = sy + y4; sxy = sxy + (x4 * y4); sx2 = sx2 + (x4 * x4); end
            endcase
        end

        // Calculate slope (m) and intercept (b)
        // m = (n*Σxy - Σx*Σy) / (n*Σx^2 - (Σx)^2)
        // b = (Σy - m*Σx) / n
        m = (5 * sxy - sx * sy) / (5 * sx2 - sx * sx);
        b = (sy - m * sx) / 5;
    end
endmodule

module nat_translation (
    input [31:0] src_ip,
    input [15:0] src_port,
    output reg [31:0] translated_ip,
    output reg [15:0] translated_port
);

always @(*) begin
    // Default values
    translated_ip = src_ip;
    translated_port = src_port;

    // NAT Translation Logic
    if (src_ip == 32'hC0A80101 && src_port == 16'h1F90) begin // 192.168.1.1 & port 8080
        translated_ip = 32'h0A000001; // 10.0.0.1
        translated_port = 16'h2301; // port 9090
    end
end

endmodule

