    parameter TIMEOUT_CYCLES = 10; // Number of clock cycles before timeout
    reg [3:0] counter; // 4-bit counter for counting cycles

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            counter <= 0;
            timeout <= 0;
        end else begin
            if (counter < TIMEOUT_CYCLES) begin
                counter <= counter + 1;
                timeout <= 0;
            end else begin
                timeout <= 1;
            end
        end
    end
endmodule

