module fir_filter (
    input wire clk,
    input wire rst,
    input wire signed [15:0] x, // 16-bit signed input
    output reg signed [15:0] y // 16-bit signed output
);
    reg signed [15:0] coeffs [0:31]; // 32 coefficients
    reg signed [15:0] samples [0:31]; // 32 input samples
    integer i;

    // Coefficients initialization
    initial begin
        coeffs[0]  = 16'd1;
        coeffs[1]  = 16'd1;
        coeffs[2]  = 16'd1;
        coeffs[3]  = 16'd1;
        coeffs[4]  = 16'd1;
        coeffs[5]  = 16'd1;
        coeffs[6]  = 16'd1;
        coeffs[7]  = 16'd1;
        coeffs[8]  = 16'd1;
        coeffs[9]  = 16'd1;
        coeffs[10] = 16'd1;
        coeffs[11] = 16'd1;
        coeffs[12] = 16'd1;
        coeffs[13] = 16'd1;
        coeffs[14] = 16'd1;
        coeffs[15] = 16'd1;
        coeffs[16] = 16'd1;
        coeffs[17] = 16'd1;
        coeffs[18] = 16'd1;
        coeffs[19] = 16'd1;
        coeffs[20] = 16'd1;
        coeffs[21] = 16'd1;
        coeffs[22] = 16'd1;
        coeffs[23] = 16'd1;
        coeffs[24] = 16'd1;
        coeffs[25] = 16'd1;
        coeffs[26] = 16'd1;
        coeffs[27] = 16'd1;
        coeffs[28] = 16'd1;
        coeffs[29] = 16'd1;
        coeffs[30] = 16'd1;
        coeffs[31] = 16'd1;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 16'd0;
            for (i = 0; i < 32; i = i + 1) begin
                samples[i] <= 16'd0;
            end
        end else begin
            // Shift samples
            for (i = 31; i > 0; i = i - 1) begin
                samples[i] <= samples[i - 1];
            end
            samples[0] <= x;

            // Compute output
            y <= 16'd0;
            for (i = 0; i < 32; i = i + 1) begin
                y <= y + (samples[i] * coeffs[i]);
            end
        end
    end
endmodule

module simple_des (  
    input wire clk,  
    input wire reset,  
    input wire [63:0] plaintext,  
    input wire [63:0] key,  
    output reg [63:0] ciphertext  
);  

    reg [63:0] L, R;  
    reg [63:0] key_schedule [0:2];  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            L <= 64'b0;  
            R <= 64'b0;  
            ciphertext <= 64'b0;  
        end else begin  
            L <= plaintext[63:32];  
            R <= plaintext[31:0];  
            key_schedule[0] <= key;  // Simplified key schedule  
            for (i = 0; i < 3; i = i + 1) begin  
                {L, R} <= {R, L ^ (R ^ key_schedule[i])}; // Simplified round function  
            end  
            ciphertext <= {R, L};  // Final output  
        end  
    end  
endmodule

module reset_controller(
    input wire clk,
    input wire rst_n,
    output reg rst_out
);
    reg [3:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rst_out <= 1'b1;
            counter <= 4'b0000;
        end else if (rst_out) begin
            if (counter < 4'b1111) begin
                counter <= counter + 1;
            end else begin
                rst_out <= 1'b0;
            end
        end
    end
endmodule

