module dma_controller (
    input clk,
    input reset,
    input start_channel_1,
    input start_channel_2,
    input [7:0] src_addr_channel_1,
    input [7:0] dest_addr_channel_1,
    input [7:0] size_channel_1,
    input [7:0] src_addr_channel_2,
    input [7:0] dest_addr_channel_2,
    input [7:0] size_channel_2,
    output reg done_channel_1,
    output reg done_channel_2
);
    reg [7:0] transferred_1;
    reg [7:0] transferred_2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            done_channel_1 <= 0;
            done_channel_2 <= 0;
            transferred_1 <= 0;
            transferred_2 <= 0;
        end else begin
            if (start_channel_1 && (transferred_1 < size_channel_1)) begin
                transferred_1 <= transferred_1 + 1;
            end
            if (transferred_1 == size_channel_1) begin
                done_channel_1 <= 1;
                transferred_1 <= 0; // Reset for next transfer
            end else begin
                done_channel_1 <= 0;
            end

            if (start_channel_2 && (transferred_2 < size_channel_2)) begin
                transferred_2 <= transferred_2 + 1;
            end
            if (transferred_2 == size_channel_2) begin
                done_channel_2 <= 1;
                transferred_2 <= 0; // Reset for next transfer
            end else begin
                done_channel_2 <= 0;
            end
        end
    end
endmodule

