module paeth_filter(  
    input [7:0] current_pixel,  
    input [7:0] left_pixel,  
    input [7:0] above_pixel,  
    input [7:0] above_left_pixel,  
    output [7:0] filtered_pixel  
);  
    wire signed [8:0] p;  
    wire signed [8:0] a;  
    wire signed [8:0] b;  
    wire signed [8:0] c;  
    wire signed [8:0] min;  

    assign a = left_pixel;  
    assign b = above_pixel;  
    assign c = above_left_pixel;  

    assign p = a + b - c;  

    assign min = ( (p - a) > 0 ? (p - a) : -(p - a) ) < ( (p - b) > 0 ? (p - b) : -(p - b) ) ? (  
        ( (p - a) > 0 ? (p - a) : -(p - a) ) < ( (p - c) > 0 ? (p - c) : -(p - c) ) ? a : c  
    ) : (  
        ( (p - b) > 0 ? (p - b) : -(p - b) ) < ( (p - c) > 0 ? (p - c) : -(p - c) ) ? b : c  
    );  

    assign filtered_pixel = ( (min == a) ? a : (min == b) ? b : c );  

endmodule

module mux2to1_16bit (  
    input [15:0] in0,  
    input [15:0] in1,  
    input sel,  
    output [15:0] out  
);  
    assign out = sel ? in1 : in0;  
endmodule

