module chebyshev_filter (
    input [4:0] x, // 5-bit input signal
    output reg [4:0] y // 5-bit output filtered signal
);
    // Coefficients for a simple Chebyshev filter (for demonstration purposes)
    parameter a0 = 5'b00001; // Example coefficient
    parameter a1 = 5'b00010; // Example coefficient
    parameter a2 = 5'b00011; // Example coefficient

    reg [4:0] temp;

    always @(*) begin
        // Simplified Chebyshev filter processing
        temp = (a0 * x) + (a1 * (x >> 1)) + (a2 * (x >> 2));
        y = temp[4:0]; // Ensure we take the lower 5 bits of the result
    end
endmodule

module iir_filter (  
    input clk,  
    input reset,  
    input signed [15:0] x,  
    output reg signed [15:0] y_out  
);  
    parameter signed [15:0] b0 = 16'd1;  
    parameter signed [15:0] b1 = 16'd1;  
    parameter signed [15:0] b2 = 16'd1;  
    parameter signed [15:0] a1 = 16'd1;  
    parameter signed [15:0] a2 = 16'd1;  

    reg signed [15:0] x_prev;  
    reg signed [15:0] x_prev2;  
    reg signed [15:0] y_prev;  
    reg signed [15:0] y_prev2;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y_out <= 16'd0;  
            x_prev <= 16'd0;  
            x_prev2 <= 16'd0;  
            y_prev <= 16'd0;  
            y_prev2 <= 16'd0;  
        end else begin  
            y_out <= (b0 * x) + (b1 * x_prev) + (b2 * x_prev2) - (a1 * y_prev) - (a2 * y_prev2);  
            x_prev2 <= x_prev;  
            x_prev <= x;  
            y_prev2 <= y_prev;  
            y_prev <= y_out;  
        end  
    end  
endmodule
